  static void Porthole(string n,float angle,float y,float outside,float inside,Transform parent){var root=Group(n,parent);root.localPosition=WindowCenter(angle,y);root.localRotation=Quaternion.LookRotation(V(Mathf.Sin(angle),0,-Mathf.Cos(angle)),Vector3.up);var rim=Group("01_Segmented_Stone_Rim",root);for(int i=0;i<20;i++){float a=i*Mathf.PI/10,b=(i+1)*Mathf.PI/10;var v=new List<Vector3>();var t=new List<int>();Vector3 oa=V(Mathf.Cos(a)*outside,Mathf.Sin(a)*outside,.60f),ob=V(Mathf.Cos(b)*outside,Mathf.Sin(b)*outside,.60f),ia=V(Mathf.Cos(a)*inside,Mathf.Sin(a)*inside,.63f),ib=V(Mathf.Cos(b)*inside,Mathf.Sin(b)*inside,.63f);Quad(v,t,oa,ob,ib,ia,Vector3.forward);Quad(v,t,oa,V(oa.x,oa.y,-.23f),V(ob.x,ob.y,-.23f),ob,oa+ob);Quad(v,t,ia,ib,V(ib.x,ib.y,-.5f),V(ia.x,ia.y,-.5f),-oa-ob);Shape("RimStone_"+(i+1).ToString("D2"),Mesh("Porthole_Stone_Ring",v,t),Vector3.zero,Vector3.one,stone[(i/4)%stone.Length],rim);}
