  {
   var prefabPath=Root+"/Prefabs/Mossy_Dome_Shelter.prefab";
   var contents=PrefabUtility.LoadPrefabContents(prefabPath);
   try{foreach(var name in new[]{"06_Surface_Moss_And_Grass","08_Ground_Island_And_Meadow"}){var part=contents.transform.Find(name);if(part)UnityEngine.Object.DestroyImmediate(part.gameObject);}PrefabUtility.SaveAsPrefabAsset(contents,prefabPath);}finally{PrefabUtility.UnloadPrefabContents(contents);}
   foreach(var pair in new[]{new[]{"Junction_Box_Sage","#929089"},new[]{"Weathered_Inner_Stone","#686762"},new[]{"Limestone_Grey","#B3B0A8"},new[]{"Limestone_Ash","#BFBCB1"},new[]{"Dark_Surface_Conduit","#686256"}}){var mat=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/"+pair[0]+".mat");mat.SetColor("_BaseColor",C(pair[1]));EditorUtility.SetDirty(mat);}
