  public static void Capture(){EditorSceneManager.OpenScene(ScenePath);var model=GameObject.Find("Mossy_Dome_Shelter");if(!model||model.transform.childCount!=6)throw new Exception("Model hierarchy invalid.");int count=0;foreach(var r in model.GetComponentsInChildren<MeshRenderer>()){count++;if(!r.GetComponent<MeshFilter>().sharedMesh)throw new Exception("Missing mesh: "+r.name);foreach(var m in r.sharedMaterials)if(!m||!m.shader||!m.shader.isSupported)throw new Exception("Invalid material: "+r.name);}var cam=Camera.main;var rt=new RenderTexture(1800,1200,24,RenderTextureFormat.ARGB32);var previous=RenderTexture.active;try{cam.targetTexture=rt;VolumeManager.instance.Update(cam.transform,1);RenderPipeline.SubmitRenderRequest(cam,new RenderPipeline.StandardRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(1800,1200,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1800,1200),0,0);image.Apply();File.WriteAllBytes(Root+"/Preview/Mossy_Dome_Prop_Study.png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{cam.targetTexture=null;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}var lines=new List<string>{"Unity "+Application.unityVersion,"Scene reopened: "+ScenePath,"Model root children: "+model.transform.childCount,"Mesh renderers under prefab root: "+count,"All mesh and material shader references valid.","Actual URP render: 1800x1200.","Model prefab connected: "+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(model),"Validation performed in isolated project; original project pipeline settings unchanged."};foreach(Transform part in model.transform)lines.Add(part.name+" / direct children: "+part.childCount);File.WriteAllLines(Root+"/Validation.txt",lines);}
